// variável: const quando não muda, let quando muda. var não se usa mais.
const nome = "Ana";
let contador = 0;

// texto com valor dentro: crase e ${}, o equivalente do f-string
console.log(`Olá, ${nome}. Você tem ${contador} tarefas.`);

// função
function media(numeros) {
  if (numeros.length === 0) return 0;
  return numeros.reduce((soma, n) => soma + n, 0) / numeros.length;
}

// função curta (arrow), o jeito mais comum hoje
const dobro = (n) => n * 2;

console.log(media([10, 8, 6]));        // 8
console.log([1, 2, 3].map(dobro));     // [ 2, 4, 6 ]

// array e objeto
const tarefas = [
  { id: 1, titulo: "Estudar", feita: false },
  { id: 2, titulo: "Revisar", feita: true },
];

const pendentes = tarefas.filter((t) => !t.feita);
console.log(pendentes.length);          // 1

for (const t of tarefas) {              // o for in do Python é o for of aqui
  console.log(t.id, t.titulo);
}

// as armadilhas
console.log(1 == "1");                  // true   compara convertendo
console.log(1 === "1");                 // false  compara valor e tipo: use este
console.log(typeof null);               // "object", um erro histórico da linguagem
console.log(Boolean(""), Boolean(0));   // false false

