// 1. média, com o caso da lista vazia
function media(numeros) {
  if (numeros.length === 0) return 0;
  return numeros.reduce((soma, n) => soma + n, 0) / numeros.length;
}

// 2. contar cada item: o dicionário virou objeto (ou Map)
function contar(itens) {
  const conta = {};
  for (const item of itens) {
    conta[item] = (conta[item] ?? 0) + 1;   // o get(chave, 0) do Python
  }
  return conta;
}

// 3. filtrar acima de um limite
const acimaDe = (numeros, limite) => numeros.filter((n) => n > limite);

console.log(media([10, 8, 6]));                    // 8
console.log(media([]));                            // 0
console.log(contar(["a", "b", "a", "c", "a"]));    // { a: 3, b: 1, c: 1 }
console.log(acimaDe([1, 5, 10, 20], 5));           // [ 10, 20 ]

// o ?? 0 é o equivalente do dicionario.get(chave, 0):
// ele só cai no 0 quando o valor é null ou undefined, e não quando é 0,
// que é a diferença pro || e a causa de bug quando o valor legítimo é zero.
